import itertools
# regions: each element of the universe is a subset-membership tuple over sets; enumerate which regions nonempty
S=['crow', 'parrot', 'eagle', 'bird']
n=len(S)
regions=list(itertools.product([0,1],repeat=n))
def holds(model,st):
    kind,a,b=st;ia,ib=S.index(a),S.index(b)
    if kind=='all': return all(not(r[ia] and not r[ib]) for r in model)
    if kind=='no': return all(not(r[ia] and r[ib]) for r in model)
    if kind=='some': return any(r[ia] and r[ib] for r in model)
models=[]
for mask in range(1,1<<len(regions)):
    m=[regions[i] for i in range(len(regions)) if mask>>i&1]
    if not all(any(r[i] for r in m) for i in range(n)): continue  # every set nonempty
    if all(holds(m,s) for s in [('all', 'crow', 'parrot'), ('all', 'eagle', 'parrot'), ('all', 'parrot', 'bird')]): models.append(m)
def follows(c): return all(holds(m,c) for m in models)
C=[('no', 'crow', 'bird'), ('some', 'bird', 'eagle'), ('all', 'bird', 'crow')]
f=[follows(c) for c in C]

# either-or: II and III contradict? check complementary pair
either_II_III = (not f[1] and not f[2]) and all(holds(m,C[1]) or holds(m,C[2]) for m in models)
opts={'A':all(f),'B':f[0] and f[2] and not f[1],'C':either_II_III,'D':f[1] and not f[0] and not f[2]}
assert opts['D']
for k in 'ABC': assert not opts[k]

