n=len(S)
regions=list(itertools.product([0,1],repeat=n))
def holds(model,st):
    kind,a,b=st;ia,ib=S.index(a),S.index(b)
    if kind=='all': return all(not(r[ia] and not r[ib]) for r in model)
    if kind=='no': return all(not(r[ia] and r[ib]) for r in model)
    if kind=='some': return any(r[ia] and r[ib] for r in model)
models=[]
for mask in range(1,1<<len(regions)):
    m=[regions[i] for i in range(len(regions)) if mask>>i&1]
    if not all(any(r[i] for r in m) for i in range(n)): continue  # every set nonempty
    if all(holds(m,s) for s in [('all', 'pea', 'veg'), ('all', 'carrot', 'veg'), ('all', 'veg', 'green')]): models.append(m)
def follows(c): return all(holds(m,c) for m in models)
